def _edge_runs(grid, axis, index, bg):
    """Return contiguous non-background runs on one outer edge."""
    h, w = len(grid), len(grid[0])
    n = w if axis == "row" else h
    vals = grid[index] if axis == "row" else [grid[r][index] for r in range(h)]
    runs = []
    i = 0
    while i < n:
        if vals[i] == bg:
            i += 1
            continue
        color, start = vals[i], i
        while i < n and vals[i] == color:
            i += 1
        runs.append((start, i, color))
    return runs


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Opposing vertical edge bars pair rows across the interior. Markers
    # extend inward from their bar and paint the corresponding paired row.
    left = _edge_runs(g, "col", 0, bg)
    right = _edge_runs(g, "col", w - 1, bg)
    vertical_pairs = [(a, b) for a in left for b in right
                      if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]]
    if vertical_pairs:
        a, b = vertical_pairs[0]
        rail_color = a[2]
        markers = []
        for r in range(h):
            for c in range(1, w - 1):
                v = g[r][c]
                if v != bg and v != rail_color and (
                    a[0] <= r < a[1] or b[0] <= r < b[1]
                ):
                    markers.append((r, c, v))
        for r, c, color in markers:
            if a[0] <= r < a[1]:
                paired_r = b[0] + r - a[0]
                for x in range(1, c):
                    g[r][x] = color
            else:
                paired_r = a[0] + r - b[0]
                for x in range(c + 1, w - 1):
                    g[r][x] = color
            g[r][c] = 4
            for x in range(1, w - 1):
                g[paired_r][x] = color
        return g

    # The transposed arrangement has paired bars on the top and bottom.
    top = _edge_runs(g, "row", 0, bg)
    bottom = _edge_runs(g, "row", h - 1, bg)
    horizontal_pairs = [(a, b) for a in top for b in bottom
                        if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]]
    if not horizontal_pairs:
        return g
    top_bar, bottom_bar = horizontal_pairs[0]
    rail_color = top_bar[2]
    marker_color = next((v for row in g for v in row
                         if v != bg and v != rail_color), None)
    if marker_color is None:
        return g

    markers = [(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
               if g[r][c] not in (bg, rail_color)]
    # Bars send vertical strokes into the grid, stopping at a marker in
    # their column. Markers turn into 4 and emit a horizontal stroke left.
    for start, end, _ in (top_bar,):
        for c in range(start, end):
            for r in range(1, h - 1):
                if (r, c) in markers:
                    g[r][c] = 4
                    break
                g[r][c] = marker_color
    for start, end, _ in (bottom_bar,):
        for c in range(start, end):
            for r in range(h - 2, 0, -1):
                if (r, c) in markers:
                    g[r][c] = 4
                    break
                g[r][c] = marker_color
    for r, c in markers:
        for x in range(c):
            g[r][x] = marker_color
        g[r][c] = 4
    return g
