                for c in range(1, w - 1):
                    if g[r][c] != bg and g[r][c] != rail:
                        markers.append((r, c, g[r][c]))
        for r, c, color in markers:
            if a[0] <= r < a[1]:
                paired_r = b[0] + r - a[0]
                for x in range(1, c):
                    g[r][x] = color
            else:
