    # each horizontal edge indicates the paired column bands. Rays run from
    # the marker toward its associated bar; paired columns are painted.
    top = runs(g[0], bg)
    bottom = runs(g[h - 1], bg)
    pairs = [(a, b) for a in top for b in bottom
             if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]]
