        for c in range(1, w - 1):
            if g[r][c] != bg and g[r][c] != rail:
                markers.append((r, c, g[r][c]))
    for r, c, color in markers:
        # The marker's column determines the corresponding top/bottom run
        # offset. Extend a perpendicular ray to its paired border run.
        if a[0] <= c < a[1]:
            paired_c = b[0] + c - a[0]
        elif b[0] <= c < b[1]:
            paired_c = a[0] + c - b[0]
        else:
