                    g[r][x] = color
            g[r][c] = 4
            for y in range(1, h - 1):
                g[y][paired_c] = color
        else:
            # Markers beyond the rail runs emit a vertical segment toward
            # the opposite horizontal edge, preserving the marker location.
            g[r][c] = 4
