 "content": "from collections import Counter


def _runs(values, background):
    result = []
    i = 0
    while i < len(values):
        if values[i] == background:
            i += 1
            continue
        color = values[i]
        start = i
        while i < len(values) and values[i] == color:
            i += 1
        result.append((start, i, color))
    return result


def transform(grid):
    """Propagate markers along paired, offset edge bars."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Locate equal-length same-color edge runs on opposing sides. A marker
    # within one run's span activates the matching position on the other.
    vertical = []
    left = _runs([g[r][0] for r in range(h)], background)
    right = _runs([g[r][w - 1] for r in range(h)], background)
    for a in left:
        for b in right:
            if a[2] == b[2] and a[1] - a[0] == b[1] - b[0]:
                vertical.append((a, b))

    if vertical:
        a, b = vertical[0]
        rail = a[2]
        markers = []
        for r in range(h):
            if a[0] <= r < a[1]:
                side, counterpart = "left", b[0] + r - a[0]
            elif b[0] <= r < b[1]:
                side, counterpart = "right", a[0] + r - b[0]
            else:
                continue
            for c in range(1, w - 1):
                color = g[r][c]
                if color != background and color != rail:
                    markers.append((r, c, color, side, counterpart))
        for r, c, color, side, counterpart in markers:
            if side == "left":
                for x in range(1, c):
                    g[r][x] = color
            else:
                for x in range(c + 1, w - 1):
                    g[r][x] = color
            g[r][c] = 4
            for x in range(1, w - 1):
                g[counterpart][x] = color
        return g

    # Same rule rotated 90 degrees: top/bottom edge runs pair columns.
    top = _runs(g[0], background)
